"""Chat tab — conversational interface to Claude via the Agent SDK."""

from __future__ import annotations

import logging
import tkinter as tk
from typing import Any

from personal_assistant.models import ConsoleLogCallback, NotifyTabCallback
from personal_assistant.config import (
    BG_INPUT,
    BG_OUTPUT,
    BG_WINDOW,
    BORDER_COLOR,
    COLOR_ASSISTANT,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    COLOR_ERROR,
    FG_ACCENT,
    FG_DIM,
    FG_TEXT,
    FONT_BODY,
    FONT_INPUT,
    PAD,
)

logger = logging.getLogger(__name__)


class ChatTab:
    """Interactive chat tab backed by ClaudeSDKClient."""

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        console_log: ConsoleLogCallback | None = None,
        notify_tab: NotifyTabCallback | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._console_log = console_log
        self._notify_tab = notify_tab
        self._client: Any = None
        self._streaming = False
        self._started = False
        self._assistant_active = False
        self._build()

    # -- UI ------------------------------------------------------------------

    def _build(self) -> None:
        # Message display area
        msg_frame = tk.Frame(self._parent, bg=BG_OUTPUT)
        msg_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=(PAD, 0))

        scrollbar = tk.Scrollbar(msg_frame)
        scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        self._messages = tk.Text(
            msg_frame,
            bg=BG_OUTPUT,
            fg=FG_TEXT,
            font=FONT_BODY,
            wrap=tk.WORD,
            state=tk.DISABLED,
            borderwidth=0,
            highlightthickness=0,
            takefocus=0,
            padx=PAD,
            pady=PAD,
            yscrollcommand=scrollbar.set,
        )
        self._messages.pack(fill=tk.BOTH, expand=True)
        scrollbar.config(command=self._messages.yview)

        # Tags for message styling
        self._messages.tag_configure("user_name", foreground=FG_ACCENT, justify=tk.LEFT)
        self._messages.tag_configure("user_msg", foreground=FG_TEXT, justify=tk.LEFT)
        self._messages.tag_configure(
            "assistant_name", foreground=COLOR_ASSISTANT, justify=tk.RIGHT
        )
        self._messages.tag_configure(
            "assistant_msg", foreground=FG_TEXT, justify=tk.RIGHT
        )
        self._messages.tag_configure("tool_msg", foreground=FG_DIM, justify=tk.RIGHT)
        self._messages.tag_configure(
            "error_msg", foreground=COLOR_ERROR, justify=tk.LEFT
        )
        self._messages.tag_configure(
            "separator", foreground=BORDER_COLOR, justify=tk.CENTER
        )

        # Input bar
        input_bar = tk.Frame(self._parent, bg=BG_WINDOW)
        input_bar.pack(fill=tk.X, padx=PAD, pady=PAD)

        self._input_var = tk.StringVar()
        self._input = tk.Entry(
            input_bar,
            textvariable=self._input_var,
            bg=BG_INPUT,
            fg=FG_TEXT,
            font=FONT_INPUT,
            insertbackground=FG_TEXT,
            relief=tk.FLAT,
        )
        self._input.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=(0, PAD))
        self._input.bind("<Return>", self._on_enter)

        btn_frame = tk.Frame(input_bar, bg=BG_WINDOW)
        btn_frame.pack(side=tk.RIGHT, fill=tk.Y, padx=(PAD, 0))

        self._send_btn = tk.Button(
            btn_frame,
            text="Send",
            command=self._send,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=8,
        )
        self._send_btn.pack(side=tk.TOP, pady=(0, 4))

        tk.Button(
            btn_frame,
            text="Clear",
            command=self._clear,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=8,
        ).pack(side=tk.TOP)

    # -- key bindings --------------------------------------------------------

    def _on_enter(self, event: tk.Event) -> str:  # type: ignore[type-arg]
        """Enter sends the message."""
        self._send()
        return "break"

    # -- send / receive ------------------------------------------------------

    def _send(self) -> None:
        """Send the current input text to Claude."""
        text = self._input_var.get().strip()
        if not text or self._streaming:
            return

        self._ensure_client()
        self._streaming = True
        self._send_btn.config(state=tk.DISABLED)
        self._assistant_active = False

        self._append_user(text)
        self._input_var.set("")

        assert self._client is not None
        self._client.send(text)

    def _ensure_client(self) -> None:
        """Lazily create and start the chat client."""
        if self._client is not None:
            return

        from personal_assistant.chat_client import ChatClient

        self._client = ChatClient(
            on_text=lambda t: self._schedule(self._on_text, t),
            on_tool_use=lambda t: self._schedule(self._on_tool_use, t),
            on_done=lambda: self._schedule(self._on_done),
            on_error=lambda e: self._schedule(self._on_error, e),
        )
        self._client.start()

    def _schedule(self, fn: Any, *args: Any) -> None:
        """Schedule a callback on the TkInter main thread."""
        if self._root.winfo_exists():
            self._root.after(0, fn, *args)

    # -- UI callbacks (main thread only) -------------------------------------

    def _on_text(self, delta: str) -> None:
        """Append streaming text delta from Claude."""
        if not self._assistant_active:
            self._start_assistant()
        self._messages.config(state=tk.NORMAL)
        self._messages.insert(tk.END, delta, "assistant_msg")
        self._messages.config(state=tk.DISABLED)
        self._messages.see(tk.END)

    def _on_tool_use(self, tool_name: str) -> None:
        """Show tool call indicator in chat."""
        self._messages.config(state=tk.NORMAL)
        if self._assistant_active:
            self._messages.insert(tk.END, "\n")
        self._messages.insert(tk.END, f"[using {tool_name}]\n", "tool_msg")
        self._messages.config(state=tk.DISABLED)
        self._messages.see(tk.END)
        if self._console_log:
            self._console_log(f"Chat: tool call → {tool_name}", "info", "", "")

    def _on_done(self) -> None:
        """Response complete."""
        self._streaming = False
        self._assistant_active = False
        self._send_btn.config(state=tk.NORMAL)
        self._messages.config(state=tk.NORMAL)
        self._messages.insert(tk.END, "\n\n")
        self._messages.config(state=tk.DISABLED)
        self._messages.see(tk.END)
        self._input.focus_set()
        if self._notify_tab:
            self._notify_tab("Chat")

    def _on_error(self, error: str) -> None:
        """Display error inline and re-enable input."""
        self._streaming = False
        self._assistant_active = False
        self._send_btn.config(state=tk.NORMAL)
        self._messages.config(state=tk.NORMAL)
        self._messages.insert(tk.END, f"\n[error] {error}\n\n", "error_msg")
        self._messages.config(state=tk.DISABLED)
        self._messages.see(tk.END)
        self._input.focus_set()
        if self._console_log:
            self._console_log(f"Chat error: {error}", "error", "", "")

    # -- message formatting --------------------------------------------------

    def _append_user(self, text: str) -> None:
        """Insert a user message into the display."""
        self._messages.config(state=tk.NORMAL)
        self._messages.insert(tk.END, "You\n", "user_name")
        self._messages.insert(tk.END, text + "\n\n", "user_msg")
        self._messages.config(state=tk.DISABLED)
        self._messages.see(tk.END)

    def _start_assistant(self) -> None:
        """Insert the Claude label before streaming text."""
        self._assistant_active = True
        self._messages.config(state=tk.NORMAL)
        self._messages.insert(tk.END, "Claude\n", "assistant_name")
        self._messages.config(state=tk.DISABLED)

    # -- clear / refresh -----------------------------------------------------

    def _clear(self) -> None:
        """Clear conversation history and display."""
        self._messages.config(state=tk.NORMAL)
        self._messages.delete("1.0", tk.END)
        self._messages.config(state=tk.DISABLED)
        if self._client:
            self._client.clear()

    def refresh(self) -> None:
        """Called when the tab is activated."""
        self._input.focus_set()

    def on_destroy(self) -> None:
        """Called during dashboard shutdown to clean up resources."""
        if self._client:
            self._client.stop()
